class Solution { public:long long minCost(vector<int>& nums,vector<int>& cost){vector<int> order(nums.size());iota(order.begin(),order.end(),0);sort(order.begin(),order.end(),[&](int a,int b){return nums[a]<nums[b];});long long total=accumulate(cost.begin(),cost.end(),0LL),cumulative=0;int target=0;for(int index:order){cumulative+=cost[index];if(cumulative*2>=total){target=nums[index];break;}}long long answer=0;for(int i=0;i<(int)nums.size();++i)answer+=llabs((long long)nums[i]-target)*cost[i];return answer;} };
